---奖励弹窗
function this:ResGetRewards(_,message)
    local cardTbl = SL:GetConfigTable("cfg_monthcard")
    for _,v in pairs(cardTbl) do
        for _,j in pairs(message) do
            if type(j) == "table" then
                if  j["cfgId"] == v.itemid then
                    return
                end
            end
        end
    end
    
    SL:OpenRewardTips(message,0,nil,nil,true)
end

function this:MessageInfo(_, message)
    SL:TipMessage(message.message, 1, message.isMidden == true and NoticeType.NoticeMid or NoticeType.NoticeLeftBottom)
end

function this:Reset(...)
    for k, tempInfo in pairs(infoList) do
        if tempInfo.Reset then
            tempInfo:Reset()
        end
    end
end
